// The sport icons (public/emblems/sports/<key>.svg) are generated by
// scripts/icons/build.py. These checks hold every file to the contract the
// generator promises, so a hand edit or a bad build fails here, not on a page.
import { test } from "node:test";
import assert from "node:assert/strict";
import { readdirSync, readFileSync } from "node:fs";

const dir = new URL("../public/emblems/sports/", import.meta.url);
const icons = readdirSync(dir).filter((f) => f.endsWith(".svg")).map((f) => [f.slice(0, -4), readFileSync(new URL(f, dir), "utf8")]);

test("every sport icon is a generated, self-contained SVG on the 120 grid", () => {
  assert.ok(icons.length >= 47, `only ${icons.length} icons`);
  for (const [key, svg] of icons) {
    assert.match(svg, /^<svg xmlns="http:\/\/www\.w3\.org\/2000\/svg" viewBox="0 0 120 120" /, key);
    assert.ok(svg.includes(`class="asnm-icon asnm-${key}"`), `${key}: missing its asnm-${key} class`);
    assert.match(svg, /role="img"><title>[^<]+<\/title>/, `${key}: needs a title`);
    assert.ok(!/<script|<image|<foreignObject|href="http|url\(http|@import/i.test(svg), `${key}: no scripts, images or outside references`);
    assert.ok(svg.length < 16 * 1024, `${key}: ${svg.length} bytes`);
  }
});

test("motion is bounded, pausable and off for reduced motion", () => {
  for (const [key, svg] of icons) {
    if (!svg.includes("@keyframes")) continue;
    assert.ok(svg.includes(`@media (prefers-reduced-motion:reduce){.asnm-${key} *{animation:none!important}}`), `${key}: reduced motion`);
    const runs = [...svg.matchAll(/animation:asnm-[^;}]*/g)].map((m) => m[0]);
    assert.ok(runs.length > 0, key);
    for (const r of runs) {
      assert.ok(r.includes("var(--asnm-loops,2)"), `${key}: loops must default to 2 (${r})`);
      assert.ok(!/infinite/.test(r), `${key}: never loops forever by default`);
    }
    assert.ok(/animation-play-state:var\(--asnm-play,running\)/.test(svg), `${key}: pausable`);
  }
});

test("ids and keyframes are namespaced per icon, so different icons can share a page", () => {
  for (const [key, svg] of icons) {
    for (const [, id] of svg.matchAll(/id="([^"]+)"/g)) assert.ok(id.startsWith(`asnm-${key}-`), `${key}: id ${id}`);
    for (const [, name] of svg.matchAll(/@keyframes ([\w-]+)/g)) assert.ok(name.startsWith(`asnm-${key}-`), `${key}: keyframes ${name}`);
    for (const [, ref] of svg.matchAll(/url\(#([^)]+)\)/g)) assert.ok(svg.includes(`id="${ref}"`), `${key}: dangling url(#${ref})`);
  }
});

test("the site's mark is the official logo (2 Sep 2026), never the retired draft", () => {
  const official = readFileSync(new URL("../scripts/icons/brand/090226_AdaptToLife_Icon.svg", import.meta.url), "utf8");
  const firstPath = official.match(/<path class="st1" d="([^"]{40})/)[1];
  for (const f of ["favicon.svg", "emblems/adaptive.svg"]) {
    const svg = readFileSync(new URL(`../public/${f}`, import.meta.url), "utf8");
    assert.ok(svg.includes(firstPath), `${f} is not drawn from the official mark`);
    assert.ok(svg.includes("Generated by scripts/icons/brand.py"), `${f} was edited by hand`);
    assert.ok(!svg.includes("M359.579 1424.07"), `${f} still carries the retired drawing`);
  }
  const fav = readFileSync(new URL("../public/favicon.svg", import.meta.url), "utf8");
  assert.ok(fav.includes("#3B3B46") && fav.includes("#FF5C39"), "favicon keeps the brand charcoal and coral");
});
